<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();$invoice=trim($_GET['invoice']??$_POST['invoice']??'');$sale=null;$err='';$msg='';if($invoice){$st=db()->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE s.invoice_no=?');$st->execute([$invoice]);$sale=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='void'){csrf_check();$reason=trim($_POST['reason']??'');if(!$sale)$err='Invoice not found.';elseif($reason==='')$err='Void reason is mandatory.';else try{db()->beginTransaction();$st=db()->prepare('SELECT * FROM sales WHERE id=? FOR UPDATE');$st->execute([$sale['id']]);$lockedSale=$st->fetch();if(!$lockedSale||$lockedSale['status']==='CANCELLED')throw new Exception('Bill already cancelled.');$st=db()->prepare('SELECT COUNT(*) FROM sale_return_items sri JOIN sale_returns sr ON sr.id=sri.sale_return_id WHERE sr.sale_id=?');$st->execute([$sale['id']]);if((int)$st->fetchColumn()>0)throw new Exception('Bill has returns. Use return workflow; void is blocked.');$st=db()->prepare('SELECT * FROM sale_items WHERE sale_id=? FOR UPDATE');$st->execute([$sale['id']]);$items=$st->fetchAll();foreach($items as $it){db()->prepare('INSERT INTO inventory_balances(product_id,batch_id,location_id,qty) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE qty=qty+VALUES(qty)')->execute([$it['product_id'],$it['batch_id'],$it['location_id'],$it['quantity']]);db()->prepare('UPDATE batches SET qty_available=qty_available+? WHERE id=?')->execute([$it['quantity'],$it['batch_id']]);if($it['serial_id']){$st2=db()->prepare("UPDATE product_serials SET status='AVAILABLE',location_id=? WHERE id=? AND status='SOLD'");$st2->execute([$it['location_id'],$it['serial_id']]);if($st2->rowCount()!==1)throw new Exception('Serial status mismatch. Void stopped.');}db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_in,reference_type,reference_id,unit_rate,remarks,created_by) VALUES('SALE_VOID',?,?,?,?, 'SALE_VOID',?,?,?,?)")->execute([$it['product_id'],$it['batch_id'],$it['location_id'],$it['quantity'],$sale['id'],$it['unit_price'],$reason,current_user()['id']]);}
 if((int)($lockedSale['customer_id']??0)>0&&(float)$lockedSale['credit_total']>0)db()->prepare("INSERT INTO customer_ledger(customer_id,txn_type,credit,reference_type,reference_id,remarks,created_by) VALUES(?,'VOID_REVERSAL',?,'SALE_VOID',?,?,?)")->execute([$lockedSale['customer_id'],$lockedSale['credit_total'],$sale['id'],$reason,current_user()['id']]);db()->prepare("UPDATE sales SET status='CANCELLED',refund_total=grand_total,cancel_reason=?,cancelled_by=?,cancelled_at=NOW() WHERE id=?")->execute([$reason,current_user()['id'],$sale['id']]);db()->commit();audit('SALE_VOID','sale',(int)$sale['id'],['invoice'=>$invoice,'reason'=>$reason]);publish_event('SALE_VOID','Bill voided',$invoice.' · stock restored',['super_admin'],'sale',(int)$sale['id'],null);publish_scoped_event('SALE_VOID_STOCK_IN','Voided bill stock restored',$invoice.' · stock restored',['manager','godown'],'sale',(int)$sale['id']);$msg='Bill voided and stock restored.';$st=db()->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE s.invoice_no=?');$st->execute([$invoice]);$sale=$st->fetch();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
page_header('Void / Cancel Bill · Super Admin');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="get" class="actions"><input name="invoice" value="<?=e($invoice)?>" placeholder="Invoice No."><button class="btn">Find</button></form><br><?php if($sale):?><div class="panel"><b><?=e($sale['invoice_no'])?></b> · <?=e($sale['created_at'])?> · <?=e($sale['cashier'])?> · ₹<?=e(number_format($sale['grand_total'],2))?> · <b><?=e($sale['status'])?></b><?php if($sale['status']!=='CANCELLED'):?><hr><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="void"><input type="hidden" name="invoice" value="<?=e($invoice)?>"><label>Mandatory Reason</label><input name="reason" required><br><br><button class="btn danger">VOID BILL & RESTORE STOCK</button></form><?php else:?><div class="notice error">Already cancelled: <?=e($sale['cancel_reason'])?></div><?php endif;?></div><?php endif;?><div class="notice"><b>Important:</b> this reverses inventory and credit ledger. For CASH/CARD/UPI, any real-world money refund must still be reconciled by your accounts team.</div><?php page_footer();
